                continue
            # Treat a marker as embedded when it lies inside the bounds of a
            # contiguous rectangular patch of 3s.
            inside = False
            for y in range(max(0, r-1), min(h, r+2)):
                for x in range(max(0, c-1), min(w, c+2)):
                    if grid[y][x] == 3:
                        inside = True
            if not inside:
                continue
            # Markers in the background are noise; require 3s on opposite
            # sides of the marker along at least one axis.
            vertical = r > 0 and r+1 < h and grid[r-1][c] == 3 and grid[r+1][c] == 3
            horizontal = c > 0 and c+1 < w and grid[r][c-1] == 3 and grid[r][c+1] == 3
            if not (vertical or horizontal):
                continue
            for y in range(max(0, r-1), min(h, r+2)):
                for x in range(max(0, c-1), min(w, c+2)):
                    if grid[y][x] == 3:
                        out[y][x] = 1
    return out
