def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    boxes = []

    # Find each 4-connected 3-region and its bounding rectangle.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 3 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            boxes.append((min(y for y, x in cells), max(y for y, x in cells),
                          min(x for y, x in cells), max(x for y, x in cells)))

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            if not any(rmin <= r <= rmax and cmin <= c <= cmax
                       for rmin, rmax, cmin, cmax in boxes):
                continue
            for y in range(max(0, r - 1), min(h, r + 2)):
                for x in range(max(0, c - 1), min(w, c + 2)):
                    if grid[y][x] != 2:
                        out[y][x] = 1
    return out
